async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  let accepted = 0;
  let rejected = 0;
  let line = 0;
  let eof = false;
  let failed = false;

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    const fragments = [];

    function append(bytes) {
      const text = decoder.decode(bytes, { stream: true });
      if (text.length > 0) fragments.push(text);
    }

    async function visitLine() {
      const text = fragments.join("");
      fragments.length = 0;
      line++;

      if (text.trim() === "") return true;

      let value;
      try {
        value = JSON.parse(text);
      } catch {
        rejected++;
        return true;
      }

      accepted++;
      return (await visitor({ line, value })) !== false;
    }

    while (true) {
      const result = await reader.read();

      if (result.done) {
        eof = true;

        const tail = decoder.decode();
        if (tail.length > 0) fragments.push(tail);

        if (fragments.length > 0 && !(await visitLine())) {
          return { accepted, rejected, stopped: true };
        }

        return { accepted, rejected, stopped: false };
      }

      const bytes = result.value;
      let start = 0;

      for (let i = 0; i < bytes.length; i++) {
        if (bytes[i] !== 0x0a) continue;

        append(bytes.subarray(start, i + 1));
        start = i + 1;

        if (!(await visitLine())) {
          return { accepted, rejected, stopped: true };
        }
      }

      if (start < bytes.length) {
        append(bytes.subarray(start));
      }
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!eof || failed) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
